#include <iostream>
#include <iomanip>
#include <stdexcept>

class Time {
public:
    explicit Time(int h = 0, int m = 0, int s = 0) {
        setTime(h, m, s);
    }

    void setTime(int h, int m, int s) {
        setHour(h);
        setMinute(m);
        setSecond(s);
    }

    void setHour(int h) {
        if (h >= 0 && h < 24) hour = h;
        else throw std::invalid_argument("hour must be 0-23");
    }

    void setMinute(int m) {
        if (m >= 0 && m < 60) minute = m;
        else throw std::invalid_argument("minute must be 0-59");
    }

    void setSecond(int s) {
        if (s >= 0 && s < 60) second = s;
        else throw std::invalid_argument("second must be 0-59");
    }

    unsigned int getHour() const { return hour; }
    unsigned int getMinute() const { return minute; }
    unsigned int getSecond() const { return second; }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << getHour() << ":"
                  << std::setw(2) << getMinute() << ":"
                  << std::setw(2) << getSecond();
    }

    void printStandard() const {
        std::cout << ((getHour() == 0 || getHour() == 12) ? 12 : getHour() % 12)
                  << ":" << std::setfill('0') << std::setw(2) << getMinute()
                  << ":" << std::setw(2) << getSecond()
                  << (hour < 12 ? " AM" : " PM");
    }

private:
    unsigned int hour{0};
    unsigned int minute{0};
    unsigned int second{0};
};

int main() {
    Time t(13, 5, 9);
    std::cout << "Universal: ";
    t.printUniversal();
    std::cout << "\nStandard: ";
    t.printStandard();
    std::cout << std::endl;
    return 0;
}

#include <iostream>
#include <iomanip>
#include <stdexcept>

class Time {
public:
    // Delegating constructors (C++11/C++17)
    Time() : Time(0, 0, 0) {} 
    explicit Time(int h) : Time(h, 0, 0) {}
    Time(int h, int m) : Time(h, m, 0) {}

    // Target constructor with validation
    Time(int h, int m, int s) {
        setTime(h, m, s);
    }

    void setTime(int h, int m, int s) {
        setHour(h);
        setMinute(m);
        setSecond(s);
    }

    void setHour(int h) {
        if (h >= 0 && h < 24) hour = h;
        else throw std::invalid_argument("hour must be 0-23");
    }

    void setMinute(int m) {
        if (m >= 0 && m < 60) minute = m;
        else throw std::invalid_argument("minute must be 0-59");
    }

    void setSecond(int s) {
        if (s >= 0 && s < 60) second = s;
        else throw std::invalid_argument("second must be 0-59");
    }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << hour << ":"
                  << std::setw(2) << minute << ":"
                  << std::setw(2) << second;
    }

private:
    unsigned int hour{0};
    unsigned int minute{0};
    unsigned int second{0};
};

int main() {
    // Uniform list initialization without '='
    Time t1{};
    Time t2{2};
    Time t3{21, 34};
    Time t4{12, 25, 42};

    std::cout << "t1: "; t1.printUniversal(); std::cout << "\n";
    std::cout << "t2: "; t2.printUniversal(); std::cout << "\n";
    std::cout << "t3: "; t3.printUniversal(); std::cout << "\n";
    std::cout << "t4: "; t4.printUniversal(); std::cout << "\n";

    try {
        Time t5{27, 74, 99};
    } catch (const std::invalid_argument& e) {
        std::cout << "Caught expected exception: " << e.what() << "\n";
    }

    return 0;
}
